import 'package:flutter/material.dart'; import 'package:intl/intl.dart'; import '../models/task.dart'; import '../services/database.dart'; import '../services/reminders.dart';
class TaskEditor extends StatefulWidget{final Task? task;const TaskEditor({super.key,this.task});@override State<TaskEditor> createState()=>_TaskEditorState();}
class _TaskEditorState extends State<TaskEditor>{final title=TextEditingController(),description=TextEditingController();late DateTime due;Priority priority=Priority.important;bool locked=false;
@override void initState(){super.initState();final t=widget.task;due=t?.dueAt??DateTime.now().add(const Duration(hours:1));if(t!=null){title.text=t.title;description.text=t.description;priority=t.priority;locked=t.locked;}}
Future<void> pick()async{final d=await showDatePicker(context:context,initialDate:due,firstDate:DateTime.now().subtract(const Duration(days:1)),lastDate:DateTime.now().add(const Duration(days:3650)));if(d==null)return;final tm=await showTimePicker(context:context,initialTime:TimeOfDay.fromDateTime(due));if(tm!=null)setState(()=>due=DateTime(d.year,d.month,d.day,tm.hour,tm.minute));}
Future<void> save()async{if(title.text.trim().isEmpty)return;final t=Task(id:widget.task?.id,title:title.text.trim(),description:description.text.trim(),dueAt:due,priority:priority,locked:locked);final id=await TaskDb.save(t);await Reminders.cancel(id);await Reminders.schedule(t.copy(id:id));if(mounted)Navigator.pop(context,true);}
@override Widget build(BuildContext c)=>Scaffold(appBar:AppBar(title:Text(widget.task==null?'NEW MISSION':'EDIT MISSION')),body:ListView(padding:const EdgeInsets.all(20),children:[TextField(controller:title,maxLength:70,decoration:const InputDecoration(labelText:'عنوان المهمة')),const SizedBox(height:12),TextField(controller:description,maxLines:3,decoration:const InputDecoration(labelText:'التفاصيل')),const SizedBox(height:20),const Text('PRIORITY PROTOCOL',style:TextStyle(color:Color(0xFF65E8FF),letterSpacing:2)),...Priority.values.map((p)=>RadioListTile(value:p,groupValue:priority,title:Text(switch(p){Priority.necessary=>'ضروري',Priority.important=>'مهم',Priority.critical=>'ضروري جداً'}),subtitle:Text(switch(p){Priority.necessary=>'تنبيه عادي',Priority.important=>'تنبيه مرتفع',Priority.critical=>'تنبيه بأولوية قصوى'}),onChanged:(v)=>setState(()=>priority=v!))),const SizedBox(height:12),OutlinedButton.icon(onPressed:pick,icon:const Icon(Icons.calendar_month),label:Text(DateFormat('yyyy/MM/dd • HH:mm').format(due))),SwitchListTile(value:locked,onChanged:(v)=>setState(()=>locked=v),title:const Text('قفل البطاقة'),subtitle:const Text('منع التعديل والحذف')),const SizedBox(height:20),FilledButton.icon(onPressed:save,icon:const Icon(Icons.save),label:const Text('حفظ المهمة'))]));}
